/* @autogenerated */
import { projectionSpec } from './repository.model';

describe('projectionSpec', () => {
  it('builds the tree from dotted paths, merging the shared prefixes', () => {
    expect(projectionSpec(['site.client.name', 'model.vendor', 'model.type', 'site'])).toEqual({
      site: { client: { name: {} } },
      model: { vendor: {}, type: {} },
    });
  });

  it('ignores empty segments', () => {
    expect(projectionSpec(['', 'model..vendor.'])).toEqual({ model: { vendor: {} } });
  });
});
